custom_css:
/* 正文气泡只包裹消息正文，名称和操作按钮保留在气泡外。 */
:root {
    --tt-bubble-max-width: 100%;
    --tt-avatar-name-gap: 10px;
    /* 头像边框额外占 4px，提前算进名称行的安全距离。 */
    --tt-avatar-slot: calc(var(--avatar-base-width) + 4px);
    --tt-floor-reserve: 5.5em;
    --tt-floor-edge-gap: 10px;
    --tt-bot-bubble: rgba(82, 59, 38, .84);
    --tt-user-bubble: rgba(99, 70, 42, .84);
}

/* 隐藏聊天滚动条，滚轮、触控板和触摸滚动仍然可用。 */
#chat {
    scrollbar-width: none;
    -ms-overflow-style: none;
    padding-right: 0 !important;
}

#chat::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
}

/* 头像与头像附属信息脱离正文流，名称行会完整预留头像高度和楼层号安全区。 */
#chat > .mes {
    position: relative;
    padding: 10px;
}

#chat > .mes > .mesAvatarWrapper {
    display: contents;
}

#chat > .mes > .mesAvatarWrapper > .avatar {
    position: absolute;
    top: 8px;
    left: 10px;
    z-index: 2;
    margin: 0;
    padding-bottom: 0 !important;
}

#chat > .mes > .mesAvatarWrapper > .mes_timer,
#chat > .mes > .mesAvatarWrapper > .tokenCounterDisplay {
    position: absolute;
    left: 10px;
    z-index: 2;
    width: var(--tt-avatar-slot);
}

#chat > .mes > .mesAvatarWrapper > .mes_timer {
    top: calc(8px + max(var(--avatar-base-height), var(--avatar-base-width)));
}

#chat > .mes > .mesAvatarWrapper > .tokenCounterDisplay {
    top: calc(8px + max(var(--avatar-base-height), var(--avatar-base-width)) + 1.2em);
}

#chat > .mes[is_user="true"] > .mesAvatarWrapper > .avatar {
    right: 10px;
    left: auto;
}

#chat > .mes[is_user="true"] > .mesAvatarWrapper > .mes_timer,
#chat > .mes[is_user="true"] > .mesAvatarWrapper > .tokenCounterDisplay {
    right: 10px;
    left: auto;
}

/* 消息块回收整行宽度；正文不再因头像永久变窄。 */
#chat > .mes > .mes_block {
    display: block;
    width: 100%;
    min-width: 0;
    padding-left: 0;
}

/* 名称和头像同一行垂直居中：角色为“头像 | 名称”，用户为“名称 | 头像”。 */
#chat > .mes > .mes_block > .ch_name {
    display: flex;
    align-items: center !important;
    min-height: max(var(--avatar-base-height), var(--avatar-base-width));
    box-sizing: border-box;
}

#chat > .mes[is_user="false"] .ch_name {
    padding-left: calc(var(--tt-avatar-slot) + var(--tt-avatar-name-gap));
    padding-right: var(--tt-floor-reserve);
}

#chat > .mes[is_user="true"] .ch_name {
    padding-left: var(--tt-floor-reserve);
    padding-right: calc(var(--tt-avatar-slot) + var(--tt-avatar-name-gap));
}

#chat > .mes[is_user="false"] .ch_name > .flex1 {
    justify-content: flex-start;
}

#chat > .mes[is_user="true"] .ch_name > .flex1 {
    justify-content: flex-end;
    text-align: right;
}

#chat > .mes .name_text {
    display: inline-flex;
    align-items: center;
    min-height: var(--mainFontSize);
}

/* 用不同色描边区分角色和用户头像，不改变原有点击行为。 */
#chat > .mes[is_user="false"] .avatar img {
    border: 2px solid color-mix(in srgb, var(--SmartThemeQuoteColor) 72%, white);
    box-shadow: 0 3px 12px rgb(0 0 0 / 28%);
}

#chat > .mes[is_user="true"] .avatar img {
    border: 2px solid color-mix(in srgb, var(--SmartThemeUnderlineColor) 78%, white);
    box-shadow: 0 3px 12px rgb(0 0 0 / 28%);
}

/* 正文独立气泡：系统消息和推理折叠区不被包进来。 */
#chat > .mes:not([is_system="true"]) .mes_text {
    display: flow-root;
    width: fit-content;
    max-width: var(--tt-bubble-max-width);
    margin-top: 4px;
    padding: 10px 14px;
    border: 1px solid color-mix(in srgb, var(--SmartThemeBorderColor) 78%, transparent);
    border-radius: 5px 18px 18px 18px;
    background: var(--tt-bot-bubble);
    box-shadow: 0 3px 12px rgb(0 0 0 / 16%);
}

#chat > .mes[is_user="true"]:not([is_system="true"]) .mes_text {
    margin-left: auto;
    border-radius: 18px 5px 18px 18px;
    background: var(--tt-user-bubble);
}

/* 嵌入式纯 HTML 运行时使用全宽气泡，普通文字仍保持自适应宽度。 */
#chat > .mes:not([is_system="true"]) .mes_text:has(> .TH-render, > .xiaobaix-iframe-wrapper),
#chat > .mes:not([is_system="true"]) .mes_text:has(> iframe) {
    width: 100%;
    box-sizing: border-box;
}

#chat > .mes:not([is_system="true"]) .mes_text > .TH-render,
#chat > .mes:not([is_system="true"]) .mes_text > .xiaobaix-iframe-wrapper,
#chat > .mes:not([is_system="true"]) .mes_text > iframe {
    display: block;
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
}

#chat > .mes:not([is_system="true"]) .mes_text > .TH-render iframe,
#chat > .mes:not([is_system="true"]) .mes_text > .xiaobaix-iframe-wrapper iframe {
    display: block;
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
}

/* 长代码和图片不突破气泡边界。 */
#chat > .mes .mes_text pre,
#chat > .mes .mes_text img:not(.mes_img) {
    max-width: 100%;
}

/* 楼层编号固定在头像对端，名称行已预留相同宽度，避免相互遮挡。 */
#chat > .mes > .mesAvatarWrapper > .mesIDDisplay {
    position: absolute;
    top: calc(10px + max(var(--avatar-base-height), var(--avatar-base-width)) / 2);
    transform: translateY(-50%);
    z-index: 3;
    display: inline-block;
    width: var(--tt-floor-reserve);
    margin: 0;
    line-height: 1;
    white-space: nowrap;
    pointer-events: none;
}

/* 角色：头像 名称 | 楼层编号。 */
#chat > .mes[is_user="false"] > .mesAvatarWrapper > .mesIDDisplay {
    right: var(--tt-floor-edge-gap);
    left: auto;
    text-align: right;
}

/* 用户：楼层编号 | 名称 头像。 */
#chat > .mes[is_user="true"] > .mesAvatarWrapper > .mesIDDisplay {
    right: auto;
    left: var(--tt-floor-edge-gap);
    text-align: left;
}

@media (max-width: 600px) {
    :root {
        --tt-avatar-name-gap: 8px;
        --tt-floor-reserve: 4.75em;
    }

    #chat > .mes {
        padding-left: 8px;
        padding-right: 8px;
    }

    #chat > .mes > .mesAvatarWrapper > .avatar,
    #chat > .mes > .mesAvatarWrapper > .mes_timer,
    #chat > .mes > .mesAvatarWrapper > .tokenCounterDisplay {
        left: 8px;
    }

    #chat > .mes[is_user="true"] > .mesAvatarWrapper > .avatar,
    #chat > .mes[is_user="true"] > .mesAvatarWrapper > .mes_timer,
    #chat > .mes[is_user="true"] > .mesAvatarWrapper > .tokenCounterDisplay {
        right: 8px;
        left: auto;
    }

    #chat > .mes[is_user="false"] > .mesAvatarWrapper > .mesIDDisplay {
        right: max(8px, env(safe-area-inset-right));
    }

    #chat > .mes[is_user="true"] > .mesAvatarWrapper > .mesIDDisplay {
        left: max(8px, env(safe-area-inset-left));
    }
}

/* 底部输入区以整体容器绘制，避免移动端默认透明背景透出。 */
body #sheld #form_sheld #send_form {
    background: rgba(70, 50, 32, .92) !important;
    opacity: 1 !important;
}

#send_textarea,
#leftSendForm > div,
#rightSendForm > div:not(.mes_stop),
#send_but,
#mes_continue,
#mes_impersonate {
    background-color: transparent !important;
}

/* 以下保留“纸张文档”的正文、Markdown 与推理区字体排版。 */
/* 聊天文本美化·纸张文档：只影响聊天正文、推理正文和 Markdown 内容 */

:root {
    --chat-font: "Noto Serif SC", sans-serif;
    --chat-body: rgba(231, 225, 207, 1);
    --chat-em: rgba(194, 171, 139, 1);
    --chat-underline: rgba(216, 172, 123, 1);
    --chat-quote: rgba(197, 143, 91, 1);
    --chat-surface: rgba(112, 80, 49, .22);
    --chat-border: rgba(205, 164, 116, .55);
    --chat-header: rgba(125, 87, 55, .52);
}

.mes_text,
.mes_reasoning {
    font-family: var(--chat-font) !important;
    font-weight: 400;
    font-size: calc(var(--mainFontSize) * var(--tt-message-font-scale, 1));
    line-height: 1.9;
    color: var(--chat-body);
    overflow-wrap: anywhere;
}

.mes_text p,
.mes_reasoning p {
    margin-top: 0;
    margin-bottom: 1.35em;
    line-height: 1.9;
    text-indent: 0;
}

.mes_text p:last-child,
.mes_reasoning p:last-child {
    margin-bottom: 0;
}

.mes_text em,
.mes_text i,
.mes_reasoning em,
.mes_reasoning i {
    color: var(--chat-em);
}

.mes_text u,
.mes_reasoning u,
.mes_text del,
.mes_text s,
.mes_reasoning del,
.mes_reasoning s {
    color: var(--chat-underline);
}

.mes_text q,
.mes_reasoning q {
    color: var(--chat-quote);
    background: color-mix(in srgb, var(--chat-quote) 20%, transparent);
    border-radius: 3px;
    padding: 0 0.18em;
}

.mes_text blockquote,
.mes_reasoning blockquote {
    margin: 0 0 1.35em;
    padding: 0.75em 1em;
    border: 1px solid var(--chat-border);
    border-left: 4px solid var(--chat-quote);
    border-radius: 0 3px 3px 0;
    background: var(--chat-surface);
}

.mes_text mark,
.mes_reasoning mark {
    padding: 0 0.25em;
    color: var(--chat-body);
    background: color-mix(in srgb, var(--chat-quote) 58%, transparent);
    border-radius: 2px;
}

.mes_text code:not(pre code),
.mes_reasoning code:not(pre code) {
    padding: 0.12em 0.4em;
    color: var(--chat-quote);
    background: var(--chat-surface);
    border: 1px solid var(--chat-border);
    border-radius: 3px;
}

.mes_text pre,
.mes_reasoning pre {
    max-height: 280px;
    overflow: auto;
    padding: 0.7em;
    font-family: var(--monoFontFamily, monospace);
    background: color-mix(in srgb, var(--chat-quote) 10%, var(--SmartThemeBlurTintColor));
    color: var(--chat-body);
    border: 1px solid var(--chat-border);
    border-radius: 3px;
}

.mes_text pre code,
.mes_reasoning pre code {
    display: block;
    padding: 0.85em;
    background: transparent !important;
    color: inherit !important;
    border: 0;
}

.mes_reasoning_header {
    padding: 0.6em 0.9em;
    color: var(--chat-body);
    background: rgba(125, 87, 55, .52);
    border: 1px solid var(--chat-border);
    border-radius: 3px;
    font-weight: 700;
}

.mes_reasoning {
    max-height: 520px;
    overflow-y: auto;
    border-left: 3px solid var(--chat-quote);
    border-radius: 0 3px 3px 0;
    padding-left: 1em;
}

.mes_text .edit_textarea,
.mes_reasoning textarea {
    font-family: var(--chat-font) !important;
    color: var(--chat-body);
}
